-- Statutory contribution schemes verified against the primary texts (11 November 2026):
--   FVO      S.B. 2019 no. 64 art. 12 lid 4 (1,0%; employee max 50%, employer min 50%; base salary per the FVO)
--   Pension  Wet Algemeen Pensioen 2014 (S.B. 2014 no. 113) art. 6 and 8; S.B. 2023 no. 118 (base SRD 2,250–22,500)
--   Health   Wet Nationale Basiszorgverzekering (S.B. 2014 no. 114) art. 7–8 (premium per insurance policy, 50/50)
-- Only UNTOUCHED default schemes are changed (not approved, no rates/amounts, not marked not applicable), so
-- anything a customer configured itself is left alone. Finalised payslips are never recalculated.

-- 1. FVO: configure and approve (unless the company already has an approved FVO scheme).
UPDATE "ContributionScheme" s SET
  "method" = 'PERCENTAGE', "base" = 'BASE_SALARY', "employeeRateBp" = 50, "employerRateBp" = 50,
  "legalStatus" = 'VERIFIED',
  "legalReference" = 'Wet Arbeidsbescherming Gezin, S.B. 2019 no. 64, art. 12 lid 4: 1,0% van het brutoloon (basisloon zonder toelagen en emolumenten, FVO), werknemer max. 50%, werkgever min. 50% — geverifieerd 11-11-2026',
  "isActive" = true, "approvedAt" = NOW(),
  "notes" = 'Automatisch ingesteld en goedgekeurd volgens de geverifieerde wettelijke regeling (zie Wettelijke bronnen).',
  "updatedAt" = NOW()
WHERE s."type" = 'FVO' AND s."basis" = 'STATUTORY' AND s."approvedAt" IS NULL AND s."notApplicable" = false
  AND s."employeeRateBp" = 0 AND s."employerRateBp" = 0 AND s."employeeAmount" = 0 AND s."employerAmount" = 0
  AND NOT EXISTS (SELECT 1 FROM "ContributionScheme" o WHERE o."companyId" = s."companyId" AND o."type" = 'FVO' AND o."approvedAt" IS NOT NULL);

-- 2. Pension: 2026 (8,5%) and 2027 (9,0%) versions, approved — not for companies that already have an approved
--    pension scheme or that record pension percentages in employment contracts (own pension arrangement).
WITH upd AS (
  UPDATE "ContributionScheme" s SET
    "method" = 'PERCENTAGE', "base" = 'REGULAR_WAGE', "employeeRateBp" = 425, "employerRateBp" = 425,
    "minBaseMonthly" = 225000, "maxBaseMonthly" = 2250000, "currency" = 'SRD',
    "effectiveFrom" = GREATEST(s."effectiveFrom", TIMESTAMP '2026-01-01'), "effectiveTo" = TIMESTAMP '2026-12-31',
    "legalStatus" = 'VERIFIED',
    "legalReference" = 'Wet Algemeen Pensioen 2014, S.B. 2014 no. 113, art. 8 lid 2: premie 8,5% in 2026 (50% werknemer / 50% werkgever, art. 8 lid 7); grondslag min. SRD 2.250 / max. SRD 22.500 per maand (art. 8 lid 3, S.B. 2023 no. 118); loon zonder overwerk, vakantie- en eindejaarsuitkeringen (art. 6) — geverifieerd 11-11-2026',
    "isActive" = true, "approvedAt" = NOW(),
    "notes" = 'Automatisch ingesteld en goedgekeurd volgens de geverifieerde wettelijke regeling (zie Wettelijke bronnen). Heeft uw bedrijf een eigen, gelijkwaardige pensioenregeling, pas de regeling dan aan.',
    "updatedAt" = NOW()
  WHERE s."type" = 'PENSION' AND s."basis" = 'STATUTORY' AND s."approvedAt" IS NULL AND s."notApplicable" = false
    AND s."employeeRateBp" = 0 AND s."employerRateBp" = 0 AND s."employeeAmount" = 0 AND s."employerAmount" = 0
    AND s."effectiveFrom" <= TIMESTAMP '2026-12-31'
    AND NOT EXISTS (SELECT 1 FROM "ContributionScheme" o WHERE o."companyId" = s."companyId" AND o."type" = 'PENSION' AND o."approvedAt" IS NOT NULL)
    AND NOT EXISTS (SELECT 1 FROM "Contract" c JOIN "Employee" e ON e."id" = c."employeeId" WHERE e."companyId" = s."companyId" AND (c."pensionEmployeeBp" > 0 OR c."pensionEmployerBp" > 0))
  RETURNING s.*
)
INSERT INTO "ContributionScheme" ("id", "companyId", "type", "name", "basis", "method", "base", "employeeRateBp", "employerRateBp", "employeeAmount", "employerAmount", "minBaseMonthly", "maxBaseMonthly", "currency", "effectiveFrom", "effectiveTo", "isActive", "appliesToAll", "employeeTax", "showOnPayslip", "legalStatus", "legalReference", "notes", "approvedAt", "notApplicable", "createdAt", "updatedAt")
SELECT 'cs' || substr(md5(random()::text || upd."id"), 1, 23), upd."companyId", upd."type", upd."name", upd."basis", upd."method", upd."base", 450, 450, 0, 0, upd."minBaseMonthly", upd."maxBaseMonthly", upd."currency", TIMESTAMP '2027-01-01', TIMESTAMP '2027-12-31', true, upd."appliesToAll", upd."employeeTax", upd."showOnPayslip", 'VERIFIED',
  'Wet Algemeen Pensioen 2014, S.B. 2014 no. 113, art. 8 lid 2: premie 9% in 2027 (50% werknemer / 50% werkgever, art. 8 lid 7); grondslag min. SRD 2.250 / max. SRD 22.500 per maand (art. 8 lid 3, S.B. 2023 no. 118); loon zonder overwerk, vakantie- en eindejaarsuitkeringen (art. 6) — geverifieerd 11-11-2026',
  upd."notes", NOW(), false, NOW(), NOW()
FROM upd;

-- 3. Health insurance: legal basis verified; the premium comes from the company's own policy (not pre-filled).
UPDATE "ContributionScheme" s SET
  "legalStatus" = 'VERIFIED',
  "legalReference" = 'Wet Nationale Basiszorgverzekering, S.B. 2014 no. 114, art. 7 lid 6–7 en art. 8: premie conform de polis van de zorgverzekeraar, 50% werknemer / 50% werkgever (werknemersdeel nooit hoger) — geverifieerd 11-11-2026; vul het maandbedrag uit uw polis in',
  "updatedAt" = NOW()
WHERE s."type" = 'HEALTH' AND s."basis" = 'STATUTORY' AND s."approvedAt" IS NULL
  AND s."employeeAmount" = 0 AND s."employerAmount" = 0 AND s."employeeRateBp" = 0 AND s."employerRateBp" = 0;

-- 4. Currency of schemes that were never configured follows the company's (current) base currency
--    (fixes e.g. "EUR 0,00" shown for SRD companies whose base currency changed after sign-up).
UPDATE "ContributionScheme" s SET "currency" = c."currency", "updatedAt" = NOW()
FROM "Company" c
WHERE c."id" = s."companyId" AND s."currency" <> c."currency" AND s."approvedAt" IS NULL
  AND s."employeeAmount" = 0 AND s."employerAmount" = 0 AND s."employeeRateBp" = 0 AND s."employerRateBp" = 0;

-- 5. Legal register: verified entries (history appended).
INSERT INTO "LegalSource" ("code","title","publication","publishedAt","effectiveFrom","subject","articles","url","verificationStatus","notes","article","state","summary","lastAmendment","lastCheckedAt","components","evidence","history","updatedAt") VALUES ('FVO','Fonds Voorzieningen Ouderschapsverlof — premie, afdracht en uitkeringen','Wet Arbeidsbescherming Gezin (S.B. 2019 no. 64), art. 12 lid 4','2019-06-10','2023-04-01','FVO-premie: 1% van het brutoloon (basisloon zonder toelagen en emolumenten); werknemer maximaal en werkgever minimaal de helft','[{"article":"12 lid 4","summary":"Bijdrage 1,0% van het brutoloon; werknemer maximaal 50%, werkgever minimaal 50%; inhouding bij elke loonbetaling en afdracht door de werkgever"},{"article":"12 lid 5","summary":"Werkgever verstrekt bij elke loonbetaling het bewijs dat de bijdrage is voldaan"},{"article":"FVO FAQ 3, 8, 12","summary":"Grondslag basisloon zonder toelagen en emolumenten; 0,5% werknemer en 0,5% werkgever; premie per 1 april 2023"}]'::jsonb,'https://www.dna.sr/media/3bjewn4q/sb_2019___64.pdf','VERIFIED','Geverifieerd tegen de wettekst (S.B. 2019 no. 64, art. 12 lid 4) en de FAQ van het Fonds. ARA Payroll stelt 0,5% werknemer en 0,5% werkgever in over het basissalaris; een werkgever mag een groter deel dragen (werknemersdeel lager).','art. 12 lid 4 en 5','IN_FORCE','Iedere werknemer en werkgever betaalt aan het Fonds een bijdrage van 1,0% van het brutoloon van de werknemer; de werknemersbijdrage is maximaal 50% en de werkgeversbijdrage minimaal 50% daarvan. De werkgever houdt de werknemersbijdrage bij elke loonbetaling in en draagt beide bijdragen af, en verstrekt de werknemer bij elke loonbetaling het bewijs van betaling. Volgens het FVO wordt de premie berekend over het basisloon zonder toelagen en emolumenten en geldt de premie per 1 april 2023. Geen maximumgrondslag.',NULL,'2026-11-11','["FVO-EE (werknemersaandeel)","FVO-ER (werkgeversaandeel)","DED012","ER007"]'::jsonb,'[{"source":"DNA — S.B. 2019 no. 64 (Wet Arbeidsbescherming Gezin), volledige tekst","url":"https://www.dna.sr/media/3bjewn4q/sb_2019___64.pdf","kind":"OFFICIAL_TEXT","finding":"Art. 12 lid 4: bijdrage gelijk aan 1.0% van het brutoloon, werknemersbijdrage maximaal 50%, werkgeversbijdrage minimaal 50%; inhouding bij elke loonbetaling.","checkedAt":"2026-11-11"},{"source":"FVO — Veelgestelde vragen","url":"https://fvo.sr/nl/faq","kind":"OFFICIAL_EXCERPT","finding":"1% van het brutoloon (basisloon zonder emolumenten), 0,5% werknemer en 0,5% werkgever; premie van kracht per 1 april 2023.","checkedAt":"2026-11-11"},{"source":"Overheid Suriname — Registratieplicht voor doorbetaald ouderschapsverlof aangevangen","url":"https://gov.sr/registratieplicht-voor-doorbetaald-ouderschapsverlof-aangevangen/","kind":"OFFICIAL_EXCERPT","finding":"Registratie vóór 15 februari 2023; inning vanaf 1 maart 2023.","checkedAt":"2026-11-03"}]'::jsonb,'[{"date":"2026-11-11","previous":"Gedeeltelijk geverifieerd; premieartikel niet ingezien.","current":"Geverifieerd: S.B. 2019 no. 64 art. 12 lid 4 — 1,0% van het brutoloon, werknemer max. 50%, werkgever min. 50%; ingang premie 1 april 2023 (FVO).","reason":"Wettekst op dna.sr en FAQ van het Fonds ingezien."}]'::jsonb,NOW()) ON CONFLICT ("code") DO UPDATE SET "title"=EXCLUDED."title","publication"=EXCLUDED."publication","publishedAt"=EXCLUDED."publishedAt","effectiveFrom"=EXCLUDED."effectiveFrom","subject"=EXCLUDED."subject","articles"=EXCLUDED."articles","url"=EXCLUDED."url","verificationStatus"=EXCLUDED."verificationStatus","notes"=EXCLUDED."notes","article"=EXCLUDED."article","state"=EXCLUDED."state","summary"=EXCLUDED."summary","lastAmendment"=EXCLUDED."lastAmendment","lastCheckedAt"=EXCLUDED."lastCheckedAt","components"=EXCLUDED."components","evidence"=EXCLUDED."evidence","history"="LegalSource"."history" || EXCLUDED."history","updatedAt"=NOW();
INSERT INTO "LegalSource" ("code","title","publication","publishedAt","effectiveFrom","subject","articles","url","verificationStatus","notes","article","state","summary","lastAmendment","lastCheckedAt","components","evidence","history","updatedAt") VALUES ('WAP-2014','Wet Algemeen Pensioen 2014','S.B. 2014 no. 113','2014-09-09','2014-12-09','Verplichte algemene pensioenregeling voor werknemers (Algemeen Pensioenfonds of gelijkwaardige eigen regeling van de werkgever)','[{"article":"6 lid 1","summary":"Loon = elke geldelijke vergoeding, behalve overwerk, tijdelijke extra werkzaamheden, vakantie-uitkeringen, winstuitkeringen, voorwaardelijke uitkeringen, onkostenvergoedingen, uitkeringen aan gezinshoofden en eindejaarsuitkeringen"},{"article":"8 lid 1–2","summary":"Premie 3% bij inwerkingtreding; vanaf 1 januari 2016 jaarlijks +0,5% tot maximaal 28% (2026: 8,5%)"},{"article":"8 lid 3 (S.B. 2023 no. 118)","summary":"Minimale bijdragegrondslag SRD 2.250, maximale SRD 22.500 per maand"},{"article":"8 lid 4–5","summary":"Minimumpremie over de minimale grondslag ongeacht het maandloon; geen premie boven de maximale grondslag"},{"article":"8 lid 7–8","summary":"Werknemer 50%, werkgever 50%; werknemersdeel nooit hoger dan werkgeversdeel"}]'::jsonb,'https://www.dna.sr/media/yjol5xwe/sb_2014__no_113_wet_algemeen_pensioen_2014.pdf','VERIFIED','Geverifieerd tegen de wettekst (DNA) en S.B. 2023 no. 118. Werkgevers met een eigen, door de Pensioenraad als gelijkwaardig beoordeelde regeling stellen hun eigen percentages in (pensioenpercentage in de arbeidsovereenkomst of een eigen regeling).','art. 2, 6 (loon), 8 (premie)','AMENDED','Premie: 3% van de bijdragegrondslag bij inwerkingtreding, vanaf 1 januari 2016 jaarlijks verhoogd met 0,5% tot maximaal 28% (art. 8 lid 1–2): 2023 7%, 2024 7,5%, 2025 8%, 2026 8,5%, 2027 9%. Verdeling bij een dienstbetrekking 50% werknemer en 50% werkgever; bij onderling overleg mag het werknemersdeel niet hoger zijn dan het werkgeversdeel (art. 8 lid 7–8). Minimale en maximale bijdragegrondslag sinds 1 januari 2023 SRD 2.250 en SRD 22.500 per maand (S.B. 2023 no. 118); de minimumpremie geldt ongeacht het maandloon (art. 8 lid 4). Loon is elke geldelijke vergoeding behalve overwerk, vergoedingen voor tijdelijke extra werkzaamheden, vakantie-uitkeringen, winstuitkeringen, voorwaardelijke uitkeringen, onkostenvergoedingen, uitkeringen aan gezinshoofden en eindejaarsuitkeringen (art. 6). Een eigen pensioenregeling die minimaal gelijkwaardig is, mag blijven (art. 2 lid 3–5).','S.B. 2023 no. 118 (art. 8 lid 3)','2026-11-11','["PENSION-EE","PENSION-ER","DED002","ER001","Pensioenpercentage arbeidsovereenkomst"]'::jsonb,'[{"source":"DNA — S.B. 2014 no. 113 Wet Algemeen Pensioen 2014 (volledige tekst)","url":"https://www.dna.sr/media/yjol5xwe/sb_2014__no_113_wet_algemeen_pensioen_2014.pdf","kind":"OFFICIAL_TEXT","finding":"Art. 8: premie 3%, vanaf 1-1-2016 jaarlijks +0,5% tot max. 28%; verdeling 50/50; art. 6: definitie loon met uitzonderingen.","checkedAt":"2026-11-11"},{"source":"S.B. 2023 no. 118 (Staatsbesluit ter uitvoering van art. 8 lid 6 WAP 2014)","url":"https://www.celerypayroll.com/wp-content/uploads/2023/10/S.B.-2023-no.-118-STAATSBESLUIT-van-7-augustus-ter-uitvoering-van-artikel-8-lid-6-van-de-Wet-Algemeen-Pensioen-2014-S.B.-2014-no.-113.pdf","kind":"OFFICIAL_TEXT","finding":"Art. I: minimale bijdragegrondslag SRD 2.250 en maximale SRD 22.500 per maand; terugwerkend tot 1 januari 2023 (art. II).","checkedAt":"2026-11-11"},{"source":"Algemeen Pensioenfonds — Veelgestelde vragen","url":"https://www.pensioen.sr/veelgestelde-vragen/","kind":"OFFICIAL_EXCERPT","finding":"Premie 2025: 8% (consistent met art. 8 lid 2).","checkedAt":"2026-11-03"}]'::jsonb,'[{"date":"2026-11-11","previous":"Gedeeltelijk geverifieerd: premie 2025 8% volgens APF, premie 2026 niet gevonden.","current":"Geverifieerd: premie volgens art. 8 lid 2 (2026: 8,5%, 2027: 9%), verdeling 50/50, grondslag SRD 2.250–22.500 per maand (S.B. 2023 no. 118).","reason":"Wettekst S.B. 2014 no. 113 en staatsbesluit S.B. 2023 no. 118 ingezien."}]'::jsonb,NOW()) ON CONFLICT ("code") DO UPDATE SET "title"=EXCLUDED."title","publication"=EXCLUDED."publication","publishedAt"=EXCLUDED."publishedAt","effectiveFrom"=EXCLUDED."effectiveFrom","subject"=EXCLUDED."subject","articles"=EXCLUDED."articles","url"=EXCLUDED."url","verificationStatus"=EXCLUDED."verificationStatus","notes"=EXCLUDED."notes","article"=EXCLUDED."article","state"=EXCLUDED."state","summary"=EXCLUDED."summary","lastAmendment"=EXCLUDED."lastAmendment","lastCheckedAt"=EXCLUDED."lastCheckedAt","components"=EXCLUDED."components","evidence"=EXCLUDED."evidence","history"="LegalSource"."history" || EXCLUDED."history","updatedAt"=NOW();
INSERT INTO "LegalSource" ("code","title","publication","publishedAt","effectiveFrom","subject","articles","url","verificationStatus","notes","article","state","summary","lastAmendment","lastCheckedAt","components","evidence","history","updatedAt") VALUES ('SB-2023-118','Staatsbesluit van 7 augustus 2023 ter uitvoering van artikel 8 lid 6 van de Wet Algemeen Pensioen 2014','S.B. 2023 no. 118','2023-08-18','2023-01-01','Minimum- en maximumgrondslag pensioenpremie','[{"article":"I","summary":"Minimale bijdragegrondslag SRD 2.250 per maand; maximale SRD 22.500 per maand"},{"article":"II lid 2","summary":"In werking de dag na afkondiging, terugwerkend tot en met 1 januari 2023"}]'::jsonb,'https://www.celerypayroll.com/wp-content/uploads/2023/10/S.B.-2023-no.-118-STAATSBESLUIT-van-7-augustus-ter-uitvoering-van-artikel-8-lid-6-van-de-Wet-Algemeen-Pensioen-2014-S.B.-2014-no.-113.pdf','VERIFIED','Tekst van het Staatsblad ingezien (gepubliceerde kopie). Geen later staatsbesluit over de grondslagen gevonden op de officiële sites; controleer jaarlijks bij het Algemeen Pensioenfonds.','art. I (nieuw art. 8 lid 3 WAP 2014), art. II','IN_FORCE','Artikel 8 lid 3 WAP 2014 luidt: de minimale bijdragegrondslag bedraagt SRD 2.250 per maand en de maximale bijdragegrondslag SRD 22.500 per maand. Uitgegeven 18 augustus 2023, terugwerkend tot en met 1 januari 2023 (index 450 × SRD 500 / SRD 5.000).',NULL,'2026-11-11','["Pensioen: minimum- en maximumgrondslag"]'::jsonb,'[{"source":"S.B. 2023 no. 118 (Staatsblad, volledige tekst)","url":"https://www.celerypayroll.com/wp-content/uploads/2023/10/S.B.-2023-no.-118-STAATSBESLUIT-van-7-augustus-ter-uitvoering-van-artikel-8-lid-6-van-de-Wet-Algemeen-Pensioen-2014-S.B.-2014-no.-113.pdf","kind":"OFFICIAL_TEXT","finding":"Minimale bijdragegrondslag SRD 2.250, maximale SRD 22.500 per maand; terugwerkend tot 1 januari 2023.","checkedAt":"2026-11-11"}]'::jsonb,'[{"date":"2026-11-11","previous":"Gedeeltelijk geverifieerd via secundaire bron (maximum genoemd als SRD 270.000 per jaar).","current":"Geverifieerd: SRD 2.250 en SRD 22.500 per maand.","reason":"Tekst van het Staatsblad ingezien."}]'::jsonb,NOW()) ON CONFLICT ("code") DO UPDATE SET "title"=EXCLUDED."title","publication"=EXCLUDED."publication","publishedAt"=EXCLUDED."publishedAt","effectiveFrom"=EXCLUDED."effectiveFrom","subject"=EXCLUDED."subject","articles"=EXCLUDED."articles","url"=EXCLUDED."url","verificationStatus"=EXCLUDED."verificationStatus","notes"=EXCLUDED."notes","article"=EXCLUDED."article","state"=EXCLUDED."state","summary"=EXCLUDED."summary","lastAmendment"=EXCLUDED."lastAmendment","lastCheckedAt"=EXCLUDED."lastCheckedAt","components"=EXCLUDED."components","evidence"=EXCLUDED."evidence","history"="LegalSource"."history" || EXCLUDED."history","updatedAt"=NOW();
INSERT INTO "LegalSource" ("code","title","publication","publishedAt","effectiveFrom","subject","articles","url","verificationStatus","notes","article","state","summary","lastAmendment","lastCheckedAt","components","evidence","history","updatedAt") VALUES ('WNBZ-2014','Wet Nationale Basiszorgverzekering','S.B. 2014 no. 114','2014-09-09','2014-10-09','Verplichte basiszorgverzekering; werkgever verzekert iedere werknemer; premie volgens de polis, verdeling 50/50','[{"article":"7 lid 1–2","summary":"Maximale premie per leeftijdscategorie (2014: 0–16 SRD 55, 17–20 SRD 75, 21–59 SRD 165, 60+ SRD 240); wijziging bij staatsbesluit"},{"article":"7 lid 6–7","summary":"Werknemer 50%, werkgever 50%; werknemersaandeel nooit hoger dan werkgeversaandeel"},{"article":"8 lid 1–2","summary":"Werkgever sluit de verzekering af, houdt het werknemersaandeel in en draagt de premie conform de polis af"}]'::jsonb,'https://www.dna.sr/media/wsxjnsrb/sb_2014__no_114_wet_nationale_basiszorgverzekering.pdf','VERIFIED','De verdeling en de verplichtingen zijn geverifieerd. Het premiebedrag is bedrijfsspecifiek: neem het maandbedrag over uit de polis van uw zorgverzekeraar (eventueel per werknemer verschillend via individuele bedragen). ARA Payroll vult geen bedrag in.','art. 4, 7, 8','IN_FORCE','Iedere werkgever sluit voor zijn werknemers een basiszorgverzekering af, maakt afspraken over de inhouding van het werknemersaandeel op het loon en draagt de premie conform de polisvoorwaarden tijdig af aan de zorgverzekeraar (art. 8). De premie is een vast bedrag per deelnemer volgens de polis van de zorgverzekeraar, binnen de wettelijke maximale premie per leeftijdscategorie (art. 7 lid 1; bij invoering SRD 55 / 75 / 165 / 240, wijziging bij staatsbesluit). Bij een dienstbetrekking: 50% werknemer, 50% werkgever; het werknemersaandeel mag nooit hoger zijn dan het werkgeversaandeel (art. 7 lid 6–7).',NULL,'2026-11-11','["HEALTH-EE","HEALTH-ER","DED004","ER002"]'::jsonb,'[{"source":"DNA — S.B. 2014 no. 114 Wet Nationale Basiszorgverzekering (volledige tekst)","url":"https://www.dna.sr/media/wsxjnsrb/sb_2014__no_114_wet_nationale_basiszorgverzekering.pdf","kind":"OFFICIAL_TEXT","finding":"Art. 7: maximale premies per leeftijdscategorie, verdeling 50/50; art. 8: verplichtingen werkgever, premie conform polisvoorwaarden.","checkedAt":"2026-11-11"},{"source":"Overheid Suriname — Basiszorgverzekering","url":"https://gov.sr/thema/basiszorgverzekering/","kind":"OFFICIAL_EXCERPT","finding":"Iedere werkgever is verplicht minimaal 50% van de premie te betalen.","checkedAt":"2026-11-03"}]'::jsonb,'[{"date":"2026-11-11","previous":"Gedeeltelijk geverifieerd; artikelnummers en premiebedragen niet bevestigd.","current":"Geverifieerd: art. 7 lid 6–7 (50/50) en art. 8 (premie conform polis); premiebedrag volgt uit de polis van de zorgverzekeraar.","reason":"Wettekst S.B. 2014 no. 114 op dna.sr ingezien."}]'::jsonb,NOW()) ON CONFLICT ("code") DO UPDATE SET "title"=EXCLUDED."title","publication"=EXCLUDED."publication","publishedAt"=EXCLUDED."publishedAt","effectiveFrom"=EXCLUDED."effectiveFrom","subject"=EXCLUDED."subject","articles"=EXCLUDED."articles","url"=EXCLUDED."url","verificationStatus"=EXCLUDED."verificationStatus","notes"=EXCLUDED."notes","article"=EXCLUDED."article","state"=EXCLUDED."state","summary"=EXCLUDED."summary","lastAmendment"=EXCLUDED."lastAmendment","lastCheckedAt"=EXCLUDED."lastCheckedAt","components"=EXCLUDED."components","evidence"=EXCLUDED."evidence","history"="LegalSource"."history" || EXCLUDED."history","updatedAt"=NOW();
